const data = $input.first().json;

console.log('=== ?? INICIANDO DEBUG DO NOVO SOP ===');

// 1. Campos que agora s�o essenciais para o novo c�lculo
const testFields = {
  // Identifica��o e Fonte
  page_id: data.notion_page_id || data.id,
  platform_detected: data.data_source_detected,

  // Metas e Contexto (Vindo do Notion)
