  if (!isOk) {
    console.error(`❌ ERRO: O campo ${key} está vazio! Verifique o n� de c�lculo anterior.`);
  }
}

// 2. Log do Objeto Completo (Para inspeção profunda no console do n8n)
console.log('=== FULL JSON OBJECT FOR INSPECTION ===');
