parameters.jsCode:
const input = $input.first().json;

const num = (value) => {
  const n = Number(value ?? 0);
  return Number.isFinite(n) ? n : 0;
};

const intNum = (value) => Math.round(num(value));
// ADR-37 D3 / ADR-38: `conversions` e FRACIONARIA (o Google Ads reporta 27,98).
// Arredondar aqui foi o que produziu o subcount da serie historica. Use num(), nunca intNum().
// clicks e impressions seguem inteiros de verdade.

const sqlString = (value) => String(value ?? '').replace(/'/g, "''");

const firstResultMetrics = (nodeName) => {
  try {
    return $(nodeName).item.json.results?.[0]?.metrics || {};
  } catch (e) {
    return {};
  }
};

// ADR-38 Fase B.1: firstResultMetrics devolve {} TANTO quando nao houve resultado
// QUANTO quando o resultado veio sem a metrica — e as duas coisas nao sao a mesma
// (R11 regra 5: o vazio tem tres caras). Para `revenue` a diferenca decide entre
// gravar NULL e gravar 0, entao precisamos perguntar pelo resultado, nao pela metrica.
const hasFirstResult = (nodeName) => {
  try {
    return !!$(nodeName).item.json.results?.[0];
  } catch (e) {
    return false;
  }
};

const getNodeJson = (nodeName) => {
  try {
    return $(nodeName).item.json || {};
  } catch (e) {
    return {};
  }
};

const context = getNodeJson('Code prepara contexto para observação');
// ADR-38: le o client_id direto da pagina do Notion. A cadeia clean_/context nao o propaga
// (o normalizador so extrai client_slug) — ver ADR-38 §9.1.
const notionProps = getNodeJson('Loop Over Items').properties || {};
const unified = getNodeJson('Code Unificar Períodos (D1, 3D, 7D)');
const calculated = getNodeJson('Code Cálcula Métricas');
const validation = getNodeJson('Code Valida Dados');

const mD1 = firstResultMetrics('HTTP Request Google Ontem (D1)');
const mD3 = firstResultMetrics('HTTP Request Google Ontem (D3)');
const mD7 = firstResultMetrics('HTTP Request Google Ontem (D7)');

const executionId = context.source_execution_id || context.execution_id || `EXEC-DE-${new Date().toISOString().replace(/[-:TZ.]/g, '').slice(0, 14)}`;
const clientId = notionProps.client_id?.rich_text?.[0]?.plain_text?.trim()
  || calculated.client_id || input.client_id || '';
const googleId = context.google_ads_id || context.raw_notion_data?.clean_id_google || calculated.google_ads_id || input.properties?.id_google_camp?.number || '';
// ADR-38: campaign_id = ID NATIVO da plataforma, sem prefixo. A coluna `platform` diz a origem.
const metaId = context.meta_campaign_id || calculated.meta_campaign_id || input.properties?.id_meta_camp?.number || '';
const nativeId = googleId || metaId || '';
const campaignId = nativeId ? String(nativeId) : '';

const cost = num(unified.raw_cost_d1 ?? calculated.raw_cost_d1 ?? calculated.cost_d1 ?? (num(mD1.costMicros) / 1000000));
const conversions = num(unified.raw_conversions_d1 ?? calculated.raw_conversions_d1 ?? mD1.conversions);
const clicks = intNum(unified.raw_clicks_d1 ?? calculated.raw_clicks_d1 ?? mD1.clicks);
const impressions = intNum(unified.raw_impressions_d1 ?? calculated.raw_impressions_d1 ?? mD1.impressions);

const cost3d = num(unified.raw_cost_3d ?? calculated.raw_cost_3d ?? calculated.cost_3d ?? (num(mD3.costMicros) / 1000000));
const conversions3d = num(unified.raw_conversions_3d ?? calculated.raw_conversions_3d ?? mD3.conversions);
const cost7d = num(calculated.raw_cost_7d ?? unified.raw_cost_7d ?? calculated.cost_7d ?? (num(mD7.costMicros) / 1000000));
const conversions7d = num(calculated.raw_conversions_7d ?? unified.raw_conversions_7d ?? mD7.conversions);

// ADR-40 (21/09): a Metrica-Mae e da CAMPANHA e viaja com ela ate raw_campaign_data.
// clean_metrica_mae vem do Code Clean Campanhas como STRING separada por virgula
// (extractMultiSelectNames faz names.join(', ')), entao pegamos a primeira.
// Vazio grava NULL, nunca um valor inventado (M4 / REQ-1 do ADR-40). Este workflow ja
// filtra 'Metrica-Mae is_not_empty' no Get many database Campanhas, entao o NULL aqui
// e cinto de seguranca, nao caminho esperado.
const primaryMetricTypeRaw = String(context.raw_notion_data?.clean_metrica_mae ?? '').split(',')[0].trim();
const primaryMetricTypeSql = primaryMetricTypeRaw ? `'${sqlString(primaryMetricTypeRaw)}'` : 'NULL';

const primaryMetricGoal = num(calculated.meta_estabelecida ?? context.meta_valor ?? context.raw_notion_data?.clean_meta_metrica_mae);
const dataSource = validation.data_source || calculated.data_source || 'google_ads_api';
const platform = context.platform === 'Google Ads' ? 'google_ads' : String(context.platform || calculated.platform || 'google_ads').toLowerCase().replace(/\s+/g, '_');

// ADR-38 Fase B.1 (etapa 8): `revenue` deixa de ser coluna exclusiva do
// PHI - Subworkflow Campanhas. Era a UNICA coisa que se perderia ao aposenta-lo
// (Fase A, 24/09) — e o Agregador a le como conv_value e a leva para o T28.
// Vem de metrics.conversions_value da MESMA GAQL que o writer 2 usa: mesmos campos,
// mesmo WHERE, mesmo DURING YESTERDAY. Isso e de proposito — para que aposentar o
// writer 2 nao mude o numero.
// M4: sem resultado da API, grava NULL, NUNCA 0. Zero e "vendeu zero", nao "nao sei".
// O Google OMITE metrica de valor zero no JSON, entao dentro de um resultado que
// EXISTE a ausencia do campo significa zero de verdade — por isso o `|| 0` do num()
// so vale depois de hasFirstResult() dizer que houve linha.
// Meta fica de fora: o writer 2 nunca cobriu Meta ("Meta Ads - em breve" e um noOp),
// entao aqui nao ha de onde tirar o valor. NULL, e nao 0.
const temResultadoD1 = hasFirstResult('HTTP Request Google Ontem (D1)');
const revenueSql = (platform === 'google_ads' && temResultadoD1)
  ? `CAST(${num(mD1.conversionsValue)} AS FLOAT64)`
  : 'CAST(NULL AS FLOAT64)';

const sql = `MERGE phi_prod.raw_campaign_data AS target
USING (
  SELECT
    '${sqlString(executionId)}' AS execution_id,
    '${sqlString(clientId)}' AS client_id,
    '${sqlString(campaignId)}' AS campaign_id,
    DATE_SUB(CURRENT_DATE('America/Sao_Paulo'), INTERVAL 1 DAY) AS date,
    CAST(${cost} AS FLOAT64) AS cost,
    CAST(${conversions} AS FLOAT64) AS conversions,
    ${revenueSql} AS revenue,
    CAST(${clicks} AS INT64) AS clicks,
    CAST(${impressions} AS INT64) AS impressions,
    CAST(${cost3d} AS FLOAT64) AS cost_3d,
    CAST(${conversions3d} AS FLOAT64) AS conversions_3d,
    CAST(${cost7d} AS FLOAT64) AS cost_7d,
    CAST(${conversions7d} AS FLOAT64) AS conversions_7d,
    CAST(${primaryMetricGoal} AS FLOAT64) AS primary_metric_goal,
    ${primaryMetricTypeSql} AS primary_metric_type,
    '${sqlString(dataSource)}' AS data_source,
    '${sqlString(platform)}' AS platform,
    'SUCCESS' AS ingestion_status,
    'DAILY_ENTRY' AS ingestion_step,
    CURRENT_TIMESTAMP() AS ingested_at
) AS source
ON  target.client_id = source.client_id
AND target.platform = source.platform
AND target.campaign_id = source.campaign_id
AND target.date = source.date
WHEN MATCHED THEN UPDATE SET
  target.cost = source.cost,
  target.conversions = source.conversions,
  -- ADR-38 Fase B.1: COALESCE de proposito. Se a consulta do D1 nao voltou, source.revenue
  -- e NULL e NULL aqui significa "nao sei" — nao pode APAGAR um valor ja gravado para a
  -- mesma campanha e o mesmo dia. Ausencia nunca destroi conhecimento (M4).
  target.revenue = COALESCE(source.revenue, target.revenue),
  target.clicks = source.clicks,
  target.impressions = source.impressions,
  target.cost_3d = source.cost_3d,
  target.conversions_3d = source.conversions_3d,
  target.cost_7d = source.cost_7d,
  target.conversions_7d = source.conversions_7d,
  target.primary_metric_goal = source.primary_metric_goal,
  target.primary_metric_type = source.primary_metric_type,
  target.data_source = source.data_source,
  target.platform = source.platform,
  target.ingestion_status = source.ingestion_status,
  target.ingested_at = source.ingested_at
WHEN NOT MATCHED THEN INSERT (
  execution_id, client_id, campaign_id, date,
  cost, conversions, revenue, clicks, impressions,
  cost_3d, conversions_3d, cost_7d, conversions_7d,
  primary_metric_goal, primary_metric_type, data_source, platform,
  ingestion_status, ingestion_step, ingested_at
) VALUES (
  source.execution_id, source.client_id, source.campaign_id, source.date,
  source.cost, source.conversions, source.revenue, source.clicks, source.impressions,
  source.cost_3d, source.conversions_3d, source.cost_7d, source.conversions_7d,
  source.primary_metric_goal, source.primary_metric_type, source.data_source, source.platform,
  source.ingestion_status, source.ingestion_step, source.ingested_at
);`;

return {
  json: {
    ...input,
    _bq_sql: sql
  }
};

