parameters.jsCode:
const data = $input.first().json;

// Fun��o auxiliar para n�meros
const toNum = (val) => {
  const n = Number(val);
  return isNaN(n) ? 0 : parseFloat(n.toFixed(2));
};

return {
  json: {
    // Usa o ID da p�gina que veio do Notion
    page_id: data.notion_page_id || data.id, 

    properties: {
      // --- CLASSIFICA��O E STATUS ---
      "Status Atual": {
        "select": { "name": data.status_meta || "Sem Dados" }
      },
      "Score Final": {
        "number": toNum(data.opt_score) // Usando o Optimization Score como Score Final
      },
      "Análise de Performance": {
        "rich_text": [{ 
          "text": { 
            "content": `🎯 Meta: ${data.meta_estabelecida} | Real: ${data.valor_real} (${data.status_meta})` 
          } 
        }]
      },

      // --- M�TRICAS DE PERFORMANCE ---
      "Meta Métrica-mãe": {
        "number": toNum(data.meta_estabelecida)
      },
      "Desvio 7D": {
        "number": toNum(data.valor_real) // Aqui voceê pode colocar o valor real atual
      },
      "Tendência 3D vs 7D": {
        "number": toNum(data.v_3d) // Exemplo: Comparativo de tend�ncia
      },

      // --- DADOS DA CAMPANHA (EXTRAS) ---
      "Última Atualização": {
        "date": { "start": new Date().toISOString() }
      },
      "Fonte do Dado": {
        "select": { "name": "Google Ads" }
      }

      // Caso queira adicionar os campos de Mensagens, Rota, etc., 
      // eles precisam ser calculados no n� anterior primeiro.
    }
  }
};

// Captura o item que vem do loop/notion
const item = $input.first();
const data = item.json;
console.log("Campos disponíveis:", Object.keys(data));

// 1. Extração Robusta da Métrica Principal
// Ordem de prioridade: campo do contexto > campo do Notion > padrão
let metric_principal = "CPA";
const campoTipo = data["Tipo da Métrica"] || (data.properties ? data.properties["Tipo da Métrica"] : null);

if (campoTipo) {
  metric_principal = campoTipo.select ? campoTipo.select.name : (typeof campoTipo === 'string' ? campoTipo : "CPA");
} else if (data.metric_principal) {
  metric_principal = data.metric_principal;
} else if (data.sop_config?.metric_principal) {
  metric_principal = data.sop_config.metric_principal;
}

// 2. Extração do Valor da Meta
// Para Google Ads: vem de Edit Fields (que lê do nó If Plataforma)
// Para Meta Ads: vem diretamente do contexto preparado
let meta_valor = 0;

try {
  // Tenta primeiro via Edit Fields (caminho Google)
  meta_valor = $('Edit Fields').first().json.meta_valor || 0;
} catch (e) {
  // Fallback para Meta Ads: usa os valores já presentes no contexto
  meta_valor = data.meta_valor ||
               data.raw_notion_data?.clean_meta_metrica_mae ||
               data.raw_notion_data?.clean_cpa_alvo ||
               0;
}

// 3. Configuração dos Limiares do SOP
const sop_thresholds = {
  'CPA': { ok_limit: 0, attention_limit: 15, critical_limit: 15, trend_alert: 10, d1_alert: 30 },
  'ROAS': { ok_limit: 0, attention_limit: 15, critical_limit: 15, trend_alert: 10, d1_alert: 30 }
};

return {
  json: {
    ...data,
    sop_config: {
      metric_principal: metric_principal,
      meta_valor: Number(meta_valor),
      thresholds: sop_thresholds[metric_principal] || sop_thresholds['CPA']
    }
  }
};

const items = $input.all();
const output = [];

const num = (value) => {
  const n = Number(value ?? 0);
  return Number.isFinite(n) ? n : 0;
};

const round = (value, digits = 2) => {
  const n = num(value);
  return Number(n.toFixed(digits));
};

const div = (numerator, denominator, multiplier = 1, digits = 2) => {
  const den = num(denominator);
  if (den <= 0) return 0;
  return round((num(numerator) / den) * multiplier, digits);
};

const emptyRaw = () => ({
  cost: 0,
  costMicros: 0,
  clicks: 0,
  impressions: 0,
  conversions: 0,
  conversionsValue: 0,
  optScore: 0,
  budget: 0,
  status: 'ESTÁVEL'
});

const addMetrics = (target, metrics = {}) => {
  const costMicros = num(metrics.costMicros ?? metrics.cost_micros);
  target.costMicros += costMicros;
  target.cost += costMicros / 1000000;
  target.clicks += num(metrics.clicks);
  target.impressions += num(metrics.impressions);
  target.conversions += num(metrics.conversions);
  target.conversionsValue += num(metrics.conversionsValue ?? metrics.conversions_value);
};

const aggregateGoogleResponse = (response, campaignId) => {
  const raw = emptyRaw();
  const rows = Array.isArray(response?.results) ? response.results : [];
  const normalizedCampaignId = campaignId ? String(campaignId) : '';

  for (const row of rows) {
    const rowCampaignId = row?.campaign?.id ? String(row.campaign.id) : '';
    if (normalizedCampaignId && rowCampaignId && rowCampaignId !== normalizedCampaignId) continue;

    addMetrics(raw, row.metrics || {});

    if (!raw.optScore && row.campaign?.optimizationScore !== undefined) {
      raw.optScore = num(row.campaign.optimizationScore) * 100;
    }
    if (!raw.budget && row.campaignBudget?.amountMicros !== undefined) {
      raw.budget = num(row.campaignBudget.amountMicros) / 1000000;
    }
    if (row.campaign?.biddingStrategySystemStatus) {
      raw.status = row.campaign.biddingStrategySystemStatus;
    }
  }

  return raw;
};

const fillFromFallback = (raw, fallback = {}) => {
  if (!raw.cost && fallback.cost !== undefined) raw.cost = num(fallback.cost);
  if (!raw.costMicros && fallback.costMicros !== undefined) raw.costMicros = num(fallback.costMicros);
  if (!raw.clicks && fallback.clicks !== undefined) raw.clicks = num(fallback.clicks);
  if (!raw.impressions && fallback.impressions !== undefined) raw.impressions = num(fallback.impressions);
  if (!raw.conversions && fallback.conversions !== undefined) raw.conversions = num(fallback.conversions);
  if (!raw.conversionsValue && fallback.conversionsValue !== undefined) raw.conversionsValue = num(fallback.conversionsValue);
  return raw;
};

const calculatePaidMediaMetrics = (raw7, raw30) => ({
  cost_7d: round(raw7.cost, 6),
  cost_30d: round(raw30.cost, 6),
  investimento_7d: round(raw7.cost, 2),
  investimento_30d: round(raw30.cost, 2),

  clicks_7d: raw7.clicks,
  clicks_30d: raw30.clicks,
  impressions_7d: raw7.impressions,
  impressions_30d: raw30.impressions,
  conversions_7d: round(raw7.conversions, 6),
  conversions_30d: round(raw30.conversions, 6),
  revenue_7d: round(raw7.conversionsValue, 6),
  revenue_30d: round(raw30.conversionsValue, 6),

  cpc_7d: div(raw7.cost, raw7.clicks),
  cpc_30d: div(raw30.cost, raw30.clicks),
  cpa_7d: div(raw7.cost, raw7.conversions),
  cpa_30d: div(raw30.cost, raw30.conversions),
  cpl_7d: div(raw7.cost, raw7.conversions),
  cpl_30d: div(raw30.cost, raw30.conversions),
  ctr_7d: div(raw7.clicks, raw7.impressions, 100),
  ctr_30d: div(raw30.clicks, raw30.impressions, 100),
  cpm_7d: div(raw7.cost, raw7.impressions, 1000),
  cpm_30d: div(raw30.cost, raw30.impressions, 1000),
  cvr_7d: div(raw7.conversions, raw7.clicks, 100),
  cvr_30d: div(raw30.conversions, raw30.clicks, 100),
  taxa_conversao_7d: div(raw7.conversions, raw7.clicks, 100),
  taxa_conversao_30d: div(raw30.conversions, raw30.clicks, 100),
  roas_7d: div(raw7.conversionsValue, raw7.cost),
  roas_30d: div(raw30.conversionsValue, raw30.cost)
});

const metricValue = (metrics, metricName) => {
  const normalized = String(metricName || '').toLowerCase();
  if (normalized === 'roas') return metrics.roas_7d;
  if (normalized === 'cpc') return metrics.cpc_7d;
  if (normalized === 'ctr') return metrics.ctr_7d;
  if (normalized === 'cpm') return metrics.cpm_7d;
  if (normalized === 'cpl') return metrics.cpl_7d;
  if (normalized === 'taxa de conversão' || normalized === 'taxa de conversao' || normalized === 'cvr') return metrics.cvr_7d;
  if (normalized === 'impressões' || normalized === 'impressoes' || normalized === 'impressions') return metrics.impressions_7d;
  return metrics.cpa_7d;
};

const lowerIsBetter = (metricName) => {
  const normalized = String(metricName || '').toLowerCase();
  return ['cpa', 'cpl', 'cpc', 'cpm', 'cac'].includes(normalized);
};

for (const item of items) {
  const data = item.json;
